try{const endpoint=new URL(state.endpoint);endpoint.searchParams.set('market',state.market);endpoint.searchParams.set('symbols',state.rows.map(row=>row.symbol).join(','));if(requestedDate)endpoint.searchParams.set('date',requestedDate);else endpoint.searchParams.delete('date');const response=await fetch(endpoint,{headers:state.token?{Authorization:'Bearer '+state.token}:{},signal:AbortSignal.timeout(90000),cache:'no-store'});let payload;try{payload=await response.json();}catch{throw new Error('行情服务没有返回有效 JSON。');}if(!response.ok)throw new Error(payload.error||'行情服务暂不可用（'+response.status+'）。');if(requestedDate&&(payload.mode!=='history'||payload.date!==requestedDate))throw new Error('行情服务未返回所选交易日的历史资金流。');const rows=normalizePayload(payload),historical=payload.mode==='history';
if(!historical){for(const row of rows){const prior=state.previous.get(row.symbol);if(prior&&prior.flowTime.slice(0,10)===row.flowTime.slice(0,10)&&prior.flowTime!==row.flowTime&&row.main!==null)row.delta=row.main-prior.main;if(row.main!==null&&row.flowTime)state.previous.set(row.symbol,{main:row.main,flowTime:row.flowTime});}}
$('connection-empty').hidden=true;state.rows=rows;state.mode=historical?'history':'live';state.date=historical?payload.date:'';state.meta={...payload,tradingDates:Array.isArray(payload.tradingDates)?payload.tradingDates.filter(date=>/^\d{4}-\d{2}-\d{2}$/.test(date)):[]};if(new URL(state.endpoint).origin===location.origin){savePreference('flow-local-live',true);savePreference('flow-history-date-'+state.market,state.date);}
$('history-date').value=state.date;$('source-label').textContent=historical?'富途 OpenD · 历史日级':'富途 OpenD · 已连接';$('source-label').style.color='var(--green)';$('status-dot').classList.add('live');const times=rows.map(row=>row.flowTime).filter(Boolean).sort();$('snapshot-time').textContent=historical?'交易日 '+state.date+' · '+marketConfig().zone+'日期':times.length?'资金有效时间 '+times.at(-1)+' '+marketConfig().clock:'资金有效时间暂不可用';const unavailable=rows.filter(row=>row.main===null).length;$('source-hint').textContent=(historical?'该交易日资金净流入 · 非分钟回放':flowSessionHint(times))+(unavailable?' · '+unavailable+' 个标的资金流不可用':'');if(unavailable){$('error').textContent=unavailable+' 个标的未返回'+(historical?'该交易日':'')+'资金流，表格显示 —。';$('error').hidden=false;}updateHistoryControls();render();notify(historical?'已加载 '+state.date+' 的资金流':'快照已获取');return true;
}catch(error){$('history-date').value=state.date;$('error').textContent=(requestedDate?'加载 '+requestedDate+' 失败：':'获取失败：')+(error.name==='TimeoutError'?'请求超时，请稍后重试。':error.message)+(state.rows.some(row=>Number.isFinite(row.main))?(state.mode==='history'?' 当前仍显示 '+state.date+' 的数据。':' 当前保留此市场上一次数据。'):' 尚未取得此市场资金流。');$('error').hidden=false;if(state.mode==='pending'){$('connection-empty').hidden=false;$('source-label').textContent='连接未成功';$('source-label').style.color='';$('source-hint').textContent='请按接入教程检查服务与行情权限';}return false;}
