/** 刷新当前数据，避免将点击事件误当作日期参数。 */
function refreshCurrent() {refresh();}
/** 查询所选市场日期；今天转为最新快照，历史休市日不自动替换。 */
function viewHistory(event) {event.preventDefault();if(state.busy)return;updateDateBounds();const date=$('history-date').value;if(!date||!$('history-date').checkValidity()){notify('请选择最近一年内、不晚于'+marketConfig().zone+'今天的日期；今天可点击“今天 / 最新”');$('history-date').value=state.date;return;}if(!state.endpoint){$('history-date').value=state.date;notify('请先连接行情服务再选择历史日期');return;}refresh(date);}
/** 按实际交易日历移动到相邻交易日。 */
function stepHistory(offset) {const dates=state.meta?.tradingDates||[],current=state.date||state.rows.map(row=>row.flowTime.slice(0,10)).filter(date=>/^\d{4}-\d{2}-\d{2}$/.test(date)).sort().at(-1),index=dates.indexOf(current);if(index>=0&&dates[index+offset])refresh(dates[index+offset]);}
/** 查询上一交易日。 */
function previousDay() {stepHistory(-1);}
/** 查询下一交易日。 */
function nextDay() {stepHistory(1);}
/** 从历史视图返回最新快照。 */
function latestFlow() {refresh('');}
/** 用真实日级数据展示截至所选日期最近最多20个交易日的主力资金趋势。 */
function historyTrend(row) {const days=row.history||[];if(!days.length)return '';const max=Math.max(1,...days.map(day=>Math.abs(day.main||0)));return '<div class="trend-title">近期主力资金动向<span>最多20个交易日 · '+marketConfig().money+'</span></div><div class="trend-chart" role="img" aria-label="主力净流入日级趋势">'+days.map(day=>'<div class="trend-day" title="'+day.date+'：'+number(day.main,0,true)+' '+marketConfig().money+'"><i class="'+(day.main<0?'out':'')+'" style="height:'+Math.abs(day.main||0)/max*48+'%"></i></div>').join('')+'</div><div class="trend-caption"><span>'+days[0].date+'</span><span>'+days.at(-1).date+'</span></div><div class="trend-list">'+days.slice(-5).map(day=>'<div><span>'+day.date+'</span><span class="'+tone(day.main)+'">'+number(day.main,0,true)+'</span></div>').join('')+'</div>';}
/** 导出当前筛选结果，带上来源与有效时间并防止表格公式注入。 */
function exportRows() {const rows=visibleRows();if(!rows.some(row=>Number.isFinite(row.main)||Number.isFinite(row.price))){notify('当前没有可导出的真实数据');return;}const headers=['来源','有效时间','股票','名称','现价','涨跌幅%','主力净流入('+marketConfig().money+')','大单','特大单(机构代理)','中单','小单','B/A','DP%','日内低','日内高','快照变化','方向'];const csv=[headers,...rows.map(row=>[state.mode==='history'?'富途OpenD·历史日级':'富途OpenD',row.flowTime,row.symbol,row.name,row.price,row.change,row.main,row.big,row.super,row.mid,row.small,row.ba,row.dp,row.low,row.high,row.delta,direction(row).label])].map(values=>values.map(value=>{let text=String(value??'');if(typeof value==='string'&&/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='资金流-'+(state.mode==='history'?'历史日级-'+state.date:'真实快照')+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已导出当前筛选结果');}
/** 断开当前接口并清空数据与令牌，避免断线后继续展示旧数据。 */
function disconnectSource() {if(state.busy)return;state.endpoint='';state.token='';state.mode='pending';state.date='';state.meta=null;state.previous.clear();state.rows=marketRows();$('token').value='';$('history-date').value='';$('source-label').textContent='未连接数据源';$('source-label').style.color='';$('snapshot-time').textContent='尚未获取真实数据';$('source-hint').textContent='点击接入数据源或查看接入教程';$('status-dot').classList.remove('live');$('connection-empty').hidden=false;$('error').hidden=true;savePreference('flow-local-disabled',true);$('connect-dialog').close();updateHistoryControls();render();}
/** 更新当前市场时钟；此时钟与资金数据时间相互独立。 */
function updateClock() {updateDateBounds();$('clock').textContent=marketDate()+' '+new Intl.DateTimeFormat('en-US',{timeZone:marketConfig().timezone,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' '+marketConfig().clock;}
/** 委托处理自选、详情、排序和分类切换。 */
function handleClick(event) {const favorite=event.target.closest('[data-favorite]'),detail=event.target.closest('[data-detail]'),sort=event.target.closest('[data-sort]'),tab=event.target.closest('[data-tab]'),close=event.target.closest('[data-close]');if(favorite){const symbol=favorite.dataset.favorite;state.favorites.has(symbol)?state.favorites.delete(symbol):state.favorites.add(symbol);savePreference('flow-favorites-'+state.market,[...state.favorites]);render();}if(detail)showDetail(detail.dataset.detail);if(sort){state.descending=state.sort===sort.dataset.sort?!state.descending:true;state.sort=sort.dataset.sort;render();}if(tab){state.tab=tab.dataset.tab;document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button===tab));render();}if(close)close.closest('dialog').close();}
/** 保存当前会话接口配置并发起首次请求。 */
async function connectSource(event) {event.preventDefault();if(state.busy)return;const endpoint=new URL($('endpoint').value.trim());if(endpoint.protocol!=='https:'&&!(endpoint.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(endpoint.hostname))){notify('在线接口请使用 HTTPS，本机接口可以使用 HTTP。');return;}if(location.protocol==='https:'&&endpoint.protocol!=='https:'){notify('线上页面需要 HTTPS 接口；本机行情请打开 http://127.0.0.1:8788/');return;}savePreference('flow-local-disabled',false);state.endpoint=endpoint.href;state.token=$('token').value;state.previous.clear();$('connect-dialog').close();await refresh();}
/** 快捷键聚焦搜索框，不干扰表单输入。 */
function handleKeyboard(event) {if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();$('search').focus();}}
document.addEventListener('click',handleClick);document.addEventListener('keydown',handleKeyboard);$('search').addEventListener('input',render);$('direction').addEventListener('change',render);$('refresh').addEventListener('click',refreshCurrent);$('history-form').addEventListener('submit',viewHistory);$('history-date').addEventListener('change',viewHistory);$('previous-day').addEventListener('click',previousDay);$('next-day').addEventListener('click',nextDay);$('latest-flow').addEventListener('click',latestFlow);$('export').addEventListener('click',exportRows);$('disconnect-source').addEventListener('click',disconnectSource);$('connect-form').addEventListener('submit',connectSource);
/** 展示接入表单，不预填远程令牌。 */
function openConnect() {if(state.busy)return;if(!$('endpoint').value)$('endpoint').value=location.hostname==='127.0.0.1'||location.hostname==='localhost'?location.origin+'/api/snapshot':'';$('connect-dialog').showModal();}
/** 展示字段来源和计算公式。 */
function openMethod() {$('method-dialog').showModal();}
/** 本机默认查询真实行情，线上等待 HTTPS 接口，不保存账户或访问令牌。 */
function initialize() {const savedMarket=readPreference('flow-market','US');state.market=markets[savedMarket]?savedMarket:'US';state.rows=marketRows();state.mode='pending';state.favorites=new Set(readPreference('flow-favorites-'+state.market,state.market==='US'?readPreference('flow-favorites',['SPY','QQQ','NVDA']):[]));applyMarket();updateHistoryControls();render();setInterval(updateClock,30000);if(['127.0.0.1','localhost'].includes(location.hostname)&&!readPreference('flow-local-disabled',false)){$('source-label').textContent='正在连接 · '+marketConfig().name;$('source-hint').textContent='正在从本机 OpenD 获取真实数据';state.endpoint=location.origin+'/api/snapshot';const saved=readPreference('flow-history-date-'+state.market,state.market==='US'?readPreference('flow-history-date',''):'');state.date=/^\d{4}-\d{2}-\d{2}$/.test(saved)&&saved>=$('history-date').min&&saved<=$('history-date').max?saved:'';refresh();}}

$('market-select').addEventListener('change',changeMarket);$('watch-form').addEventListener('submit',addWatchSymbol);
$('connect').addEventListener('click',openConnect);$('method').addEventListener('click',openMethod);$('help').addEventListener('click',openMethod);initialize();

/** 格式化收益或命中率的百分比。 */
function percent(value,digits=2) {return Number.isFinite(value)?number(value*100,digits)+'%':'—';}
/** 显示IC或收益差的95%区间，不把未跨零区间写成交易保证。 */
function confidence(interval,isReturn=false) {return Array.isArray(interval)&&interval.length===2?'['+(isReturn?percent(interval[0]):number(interval[0],3))+', '+(isReturn?percent(interval[1]):number(interval[1],3))+']':'样本不足';}
/** 展示本地真实历史数据的验证结果及可复核限制。 */
async function showValidation() {if(state.market!=='US'){notify('现有历史研究仅覆盖美股');return;}
$('validation-dialog').showModal();$('validation-content').innerHTML='<p>正在读取历史验证结果…</p>';
try{if(!state.endpoint)throw new Error('请先连接本地行情服务。');const endpoint=new URL(state.endpoint);endpoint.pathname=endpoint.pathname.replace(/\/snapshot$/, '/validation');endpoint.search='';const response=await fetch(endpoint,{headers:state.token?{Authorization:'Bearer '+state.token}:{},signal:AbortSignal.timeout(10000),cache:'no-store'}),report=await response.json();if(!response.ok)throw new Error(report.error||'验证结果暂不可用。');if(!Array.isArray(report.horizons)||!Array.isArray(report.coverage))throw new Error('验证结果格式错误。');const evidence=report.horizons.filter(item=>item.late?.ic_ci?.[0]>0&&item.late?.spread_ci?.[0]>0),verdict=evidence.length?'部分周期在时间后段出现正向证据，但这仍是一次探索性检验，需要更长样本和独立复核。':'时间后段复核中，尚未发现同时具备正IC与正分组收益差的稳健证据。资金流与当日价格同步不等于能够预测后续股价。';
$('validation-content').innerHTML='<p>'+escapeHtml(report.start)+' 至 '+escapeHtml(report.end)+' · '+report.available_symbols+' / '+report.requested_symbols+' 个标的 · '+report.trading_days+' 个交易日 · 基准 SPY</p><div class="validation-grid"><div><span>当日同步相关（平均IC）</span><strong>'+number(report.same_day_ic,3)+'</strong><small>95%区间 '+confidence(report.same_day_ic_ci)+'</small></div><div><span>验证的后续周期</span><strong>1 / 5 / 20</strong><small>交易日 · 前复权收盘价格变化</small></div><div><span>时间后段复核起点</span><strong style="font-size:19px">'+escapeHtml(report.split)+'</strong><small>最后30%时间 · 前段收益跨界样本剔除</small></div></div><div class="validation-note">'+verdict+'</div><h3 class="validation-heading">全样本：方向命中是否优于上涨基线</h3><div class="validation-scroll"><table><thead><tr><th>随后交易日</th><th>有效方向样本</th><th>整体上涨率</th><th>流入后上涨率</th><th>流出后上涨率</th><th>方向命中率</th><th>平均IC</th></tr></thead><tbody>'+report.horizons.map(item=>{const result=item.all;return '<tr><td>'+item.horizon+' 日</td><td>'+number(result.classification_n)+'</td><td>'+percent(result.baseline_up)+'</td><td>'+percent(result.inflow_up)+'</td><td>'+percent(result.outflow_up)+'</td><td>'+percent(result.direction_accuracy)+'</td><td>'+number(result.ic,3)+'</td></tr>';}).join('')+'</tbody></table></div><h3 class="validation-heading">时间后段：同一信号在后30%区间是否稳定</h3><div class="validation-scroll"><table><thead><tr><th>随后交易日</th><th>观察日数</th><th>平均IC</th><th>IC 95%区间</th><th>强流入组−弱流入组</th><th>收益差95%区间</th></tr></thead><tbody>'+report.horizons.map(item=>{const result=item.late;return '<tr><td>'+item.horizon+' 日</td><td>'+number(result.dates)+'</td><td>'+number(result.ic,3)+'</td><td>'+confidence(result.ic_ci)+'</td><td>'+percent(result.quartile_spread)+'</td><td>'+confidence(result.spread_ci,true)+'</td></tr>';}).join('')+'</tbody></table></div><p>IC是每天资金强度与随后收益的秩相关，再按交易日等权平均。资金强度 = 主力净流入 / 当日成交额。正IC表示资金越强，后续收益越高；接近0表示排序关系弱。强、弱两组分别为当天资金强度最高和最低的四分之一标的。</p><p>主力流入预测上涨、流出预测下跌。整体上涨率相当于同一非零样本上始终看涨的基线。样本数是“标的×日期”，不是独立事件数。95%区间通过连续交易日区块重采样计算，多日收益有重叠。收盘至未来收盘收益不等同可成交策略收益。</p><ul class="limits">'+report.method.limits.map(limit=>'<li>'+escapeHtml(limit)+'</li>').join('')+'</ul><p>单个标的覆盖：'+report.coverage.map(item=>escapeHtml(item.symbol)+' '+item.days+' 天').join(' · ')+'</p>'+(report.failures.length?'<p class="validation-error">有 '+report.failures.length+' 个数据获取失败项目，已从结果中排除。</p>':'');
}catch(error){$('validation-content').innerHTML='<p class="validation-error">'+escapeHtml(error.message)+'</p>';}}
$('validation').addEventListener('click',showValidation);

let pathReport=null, pathBusy=false;
const pathMetrics={main:'主力',total:'全部成交',big:'大单',super:'特大单',mid:'中单',small:'小单'};
/** 打开单股事件观察，沿用所选历史日期并允许输入当前市场其他股票代码。 */
function openPath(symbol=marketConfig().example) {
if(pathBusy){if(!$('path-dialog').open)$('path-dialog').showModal();return;}
const dates=state.meta?.tradingDates||[];
$('path-symbol').value=symbol;$('path-symbols').innerHTML=state.rows.map(row=>'<option value="'+row.symbol+'">'+escapeHtml(row.name)+'</option>').join('');
$('path-date').min=$('history-date').min;$('path-date').max=marketDate(-1);
$('path-date').value=state.date||dates.at(-21)||'';
if($('detail-dialog').open)$('detail-dialog').close();
if(!$('path-dialog').open)$('path-dialog').showModal();
if(!pathBusy){pathReport=null;$('path-content').innerHTML='';if($('path-date').value&&state.endpoint)queryPath();}
}
/** 读取独立单股历史序列，不修改总览中的日期、排序或样例数据。 */
async function queryPath(event) {
if(event)event.preventDefault();if(pathBusy||!$('path-form').reportValidity())return;
pathBusy=true;pathReport=null;['path-symbol','path-date','path-days','path-query'].forEach(id=>{$(id).disabled=true;});$('path-query').textContent='正在查询…';$('path-content').innerHTML='<p>正在读取真实历史资金流与日K线…</p>';
try{if(!state.endpoint)throw new Error('请先接入行情服务获取真实历史数据。');const endpoint=new URL(state.endpoint);endpoint.pathname=endpoint.pathname.replace(/\/snapshot$/, '/path');endpoint.search='';endpoint.searchParams.set('market',state.market);endpoint.searchParams.set('symbol',marketSymbol($('path-symbol').value));endpoint.searchParams.set('date',$('path-date').value);endpoint.searchParams.set('days',$('path-days').value);
const response=await fetch(endpoint,{headers:state.token?{Authorization:'Bearer '+state.token}:{},signal:AbortSignal.timeout(90000),cache:'no-store'});let report;try{report=await response.json();}catch{throw new Error('行情服务没有返回有效的走势数据。');}if(!response.ok)throw new Error(report.error||'走势查询暂不可用。');if(report.source!=='futu-opend'||report.adjustment!=='QFQ'||report.unit!==marketConfig().unit||report.market!==state.market||!Array.isArray(report.rows)||!report.rows.length||report.rows[0].date!==$('path-date').value)throw new Error('历史走势数据格式错误。');pathReport=report;renderPath();
}catch(error){$('path-content').innerHTML='<p class="validation-error" role="alert">'+escapeHtml(error.name==='TimeoutError'?'查询超时，请稍后重试。':error.message)+'</p>';}
finally{pathBusy=false;['path-symbol','path-date','path-days','path-query'].forEach(id=>{$(id).disabled=false;});$('path-query').textContent='查看每天走向';}
}
/** 绘制以事件日收盘为零点的累计涨跌曲线；缺失行情保留断点。 */
function pathChart(rows) {
const values=rows.map(row=>row.cumulative).filter(Number.isFinite);if(values.length<2)return '<p>后续有效行情不足，暂无法绘制走势。</p>';
const width=820,height=230,left=64,right=18,top=18,bottom=35,min=Math.min(0,...values),max=Math.max(0,...values),padding=Math.max((max-min)*.12,.2),low=min-padding,high=max+padding;
const x=i=>left+i/Math.max(1,rows.length-1)*(width-left-right),y=v=>top+(high-v)/(high-low)*(height-top-bottom);
let drawing='',connected=false;rows.forEach((row,i)=>{if(!Number.isFinite(row.cumulative)){connected=false;return;}drawing+=(connected?' L':' M')+x(i).toFixed(2)+','+y(row.cumulative).toFixed(2);connected=true;});
return '<div class="path-chart"><svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="从事件日收盘起的逐交易日累计涨跌曲线">'+[high,(high+low)/2,low].map(value=>'<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(value)+'" y2="'+y(value)+'" stroke="#263039"/><text x="'+(left-10)+'" y="'+(y(value)+4)+'" text-anchor="end">'+number(value,2)+'%</text>').join('')+'<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(0)+'" y2="'+y(0)+'" stroke="#83928d" stroke-dasharray="4 4"/><path d="'+drawing+'" fill="none" stroke="#b7eccd" stroke-width="2.5"/>'+rows.map((row,i)=>Number.isFinite(row.cumulative)?'<circle cx="'+x(i)+'" cy="'+y(row.cumulative)+'" r="3" fill="'+(row.cumulative<0?'#f47b7a':'#53d6a0')+'"><title>'+escapeHtml(row.date)+' · 收盘 '+number(row.close,2)+' · 累计 '+number(row.cumulative,2,true)+'%</title></circle>':'').join('')+'<text x="'+left+'" y="'+(height-9)+'">'+rows[0].date+' · 起点</text><text x="'+(width-right)+'" y="'+(height-9)+'" text-anchor="end">'+rows.at(-1).date+' · 第'+rows.at(-1).day+'日</text></svg></div>';
}
/** 展示事件日净资金与后续逐日价格，明确区分当日涨跌和累计涨跌。 */
function renderPath() {
if(!pathReport)return;const report=pathReport,rows=report.rows,metric=$('path-metric').value,label=pathMetrics[metric],anchor=rows[0],last=rows.at(-1),flow=anchor[metric],direction=Number.isFinite(flow)?flow>0?'净流入':flow<0?'净流出':'净额为零':'资金缺失';
const future=rows.slice(1).filter(row=>Number.isFinite(row.change)),up=future.filter(row=>row.change>0).length,down=future.filter(row=>row.change<0).length,flat=future.filter(row=>row.change===0).length;
$('path-content').innerHTML='<h3 class="validation-heading">'+escapeHtml(report.symbol)+' / '+escapeHtml(report.name)+' · '+escapeHtml(report.date)+'</h3><div class="validation-grid"><div><span>事件日 · '+label+direction+'（'+marketConfig().money+'）</span><strong class="'+tone(flow)+'">'+number(flow,0,true)+'</strong><small>当天完整交易日净额</small></div><div><span>第 '+last.day+' 日 · 相对起点累计涨跌</span><strong class="'+tone(last.cumulative)+'">'+number(last.cumulative,2,true)+(Number.isFinite(last.cumulative)?'%':'')+'</strong><small>'+escapeHtml(last.date)+' · 收盘 '+number(last.close,2)+'</small></div><div><span>后续每天的上涨 / 下跌 / 持平</span><strong>'+up+' / '+down+' / '+flat+'</strong><small>有效单日涨跌 '+future.length+' 天，共请求 '+report.requestedDays+' 个交易日</small></div></div>'+(report.availableDays<report.requestedDays?'<div class="validation-note">截至 '+escapeHtml(report.asOf)+'，此后仅有 '+report.availableDays+' 个已结束交易日，尚未满 '+report.requestedDays+' 日。</div>':'')+pathChart(rows)+'<p>虚线为事件日收盘基准（0%）。单日涨跌与上一交易日收盘比较；累计涨跌与 '+escapeHtml(report.date)+' 收盘比较。价格：'+marketConfig().currency+'／前复权；资金：'+marketConfig().money+'／净额。缺失项显示 —。</p><div class="path-table"><table><thead><tr><th>交易日</th><th>'+marketConfig().zone+'日期</th><th>收盘价</th><th>单日涨跌</th><th>相对起点累计</th><th>'+label+'净流入</th><th>当天价格方向</th></tr></thead><tbody>'+rows.map(row=>'<tr class="'+(row.day===0?'path-anchor':'')+'"><td>'+(row.day===0?'起点 T+0':'T+'+row.day)+'</td><td>'+escapeHtml(row.date)+'</td><td>'+number(row.close,2)+'</td><td class="'+tone(row.change)+'">'+number(row.change,2,true)+(Number.isFinite(row.change)?'%':'')+'</td><td class="'+tone(row.cumulative)+'">'+number(row.cumulative,2,true)+(Number.isFinite(row.cumulative)?'%':'')+'</td><td class="'+tone(row[metric])+'">'+number(row[metric],0,true)+'</td><td>'+(Number.isFinite(row.change)?row.change>0?'↑ 上涨':row.change<0?'↓ 下跌':'→ 持平':'行情缺失')+'</td></tr>').join('')+'</tbody></table></div><p>这是单个历史事件的实际走势，无法单独证明资金流具有预测能力。日级资金流在事件日结束后才完整，图中的累计涨跌不等同下一日可成交的策略收益。</p>';
}
/** 从标的详情直接进入该股票的后续走势。 */
function handlePathClick(event) {const target=event.target.closest('[data-path]');if(target)openPath(target.dataset.path);}
/** 从总览打开默认股票的逐日观察。 */
function openDefaultPath() {openPath();}
$('path-open').addEventListener('click',openDefaultPath);$('path-form').addEventListener('submit',queryPath);$('path-metric').addEventListener('change',renderPath);document.addEventListener('click',handlePathClick);

let mainWindowBusy=false;
/** 打开截至某天最近X个交易日的主力区间查询，沿用当前历史日期。 */
function openMainWindow(symbol=marketConfig().example) {
if(mainWindowBusy){if(!$('main-window-dialog').open)$('main-window-dialog').showModal();return;}
$('main-window-symbol').value=symbol;$('path-symbols').innerHTML=state.rows.map(row=>'<option value="'+row.symbol+'">'+escapeHtml(row.name)+'</option>').join('');
$('main-window-date').min=$('history-date').min;$('main-window-date').max=marketDate(-1);
$('main-window-date').value=state.date||state.meta?.tradingDates?.at(-1)||marketDate(-1);
if($('detail-dialog').open)$('detail-dialog').close();
if(!$('main-window-dialog').open)$('main-window-dialog').showModal();
$('main-window-content').innerHTML='';if(state.endpoint)queryMainWindow();else $('main-window-content').innerHTML='<p>请先接入行情服务获取真实区间资金。</p>';
}
/** 查询真实主力日级净额，仅将完整交易日纳入区间。 */
async function queryMainWindow(event) {
if(event)event.preventDefault();if(mainWindowBusy||!$('main-window-form').reportValidity())return;
mainWindowBusy=true;['main-window-symbol','main-window-date','main-window-days','main-window-query'].forEach(id=>{$(id).disabled=true;});$('main-window-query').textContent='正在查询…';$('main-window-content').innerHTML='<p>正在读取主力区间资金…</p>';
try{if(!state.endpoint)throw new Error('请先接入本地行情服务。');const endpoint=new URL(state.endpoint);endpoint.pathname=endpoint.pathname.replace(/\/snapshot$/, '/main-window');endpoint.search='';const symbol=marketSymbol($('main-window-symbol').value),date=$('main-window-date').value;endpoint.searchParams.set('market',state.market);endpoint.searchParams.set('symbol',symbol);endpoint.searchParams.set('date',date);endpoint.searchParams.set('days',$('main-window-days').value);
const response=await fetch(endpoint,{headers:state.token?{Authorization:'Bearer '+state.token}:{},signal:AbortSignal.timeout(90000),cache:'no-store'});let report;try{report=await response.json();}catch{throw new Error('行情服务没有返回有效的区间数据。');}if(!response.ok)throw new Error(report.error||'区间资金查询暂不可用。');if(report.source!=='futu-opend'||report.unit!==marketConfig().unit||report.market!==state.market||report.symbol!==symbol||report.date!==date||!Array.isArray(report.rows)||!report.rows.length||report.rows.at(-1).date!==date)throw new Error('主力区间数据格式错误。');renderMainWindow(report);
}catch(error){$('main-window-content').innerHTML='<p class="validation-error" role="alert">'+escapeHtml(error.name==='TimeoutError'?'查询超时，请稍后重试。':error.message)+'</p>';}
finally{mainWindowBusy=false;['main-window-symbol','main-window-date','main-window-days','main-window-query'].forEach(id=>{$(id).disabled=false;});$('main-window-query').textContent='查看区间资金';}
}
/** 同一金额坐标绘制每日净额柱和累计净额线，缺失累计数据保留断点。 */
function mainWindowChart(rows) {
const values=rows.flatMap(row=>[row.main,row.cumulativeMain]).filter(Number.isFinite);if(!values.length)return '';
const width=840,height=245,left=82,right=18,top=18,bottom=34,min=Math.min(0,...values),max=Math.max(0,...values),padding=Math.max((max-min)*.12,1),low=min-padding,high=max+padding;
const x=i=>left+(i+.5)/rows.length*(width-left-right),y=value=>top+(high-value)/(high-low)*(height-top-bottom),barWidth=Math.max(1,Math.min(24,(width-left-right)/rows.length*.55));
let drawing='',connected=false;rows.forEach((row,i)=>{if(!Number.isFinite(row.cumulativeMain)){connected=false;return;}drawing+=(connected?' L':' M')+x(i).toFixed(2)+','+y(row.cumulativeMain).toFixed(2);connected=true;});
return '<div class="window-chart-legend"><span class="positive">■ 每日净流入</span><span class="negative">■ 每日净流出</span><span class="accent">━ 区间累计净额</span><span class="muted">单位：'+marketConfig().money+'</span></div><div class="path-chart"><svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="主力每日净流入流出及区间累计净额">'+[high,(high+low)/2,low].map(value=>'<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(value)+'" y2="'+y(value)+'" stroke="#263039"/><text x="'+(left-10)+'" y="'+(y(value)+4)+'" text-anchor="end">'+number(value,0,true)+'</text>').join('')+'<line x1="'+left+'" x2="'+(width-right)+'" y1="'+y(0)+'" y2="'+y(0)+'" stroke="#83928d" stroke-dasharray="4 4"/>'+rows.map((row,i)=>Number.isFinite(row.main)?'<rect x="'+(x(i)-barWidth/2)+'" y="'+Math.min(y(0),y(row.main))+'" width="'+barWidth+'" height="'+Math.max(.7,Math.abs(y(row.main)-y(0)))+'" fill="'+(row.main<0?'#f47b7a':'#53d6a0')+'" opacity=".6"><title>'+escapeHtml(row.date)+' · 主力净额 '+number(row.main,0,true)+' '+marketConfig().money+'</title></rect>':'').join('')+'<path d="'+drawing+'" fill="none" stroke="#b7eccd" stroke-width="2.5"/>'+rows.map((row,i)=>Number.isFinite(row.cumulativeMain)?'<circle cx="'+x(i)+'" cy="'+y(row.cumulativeMain)+'" r="2.5" fill="#b7eccd"><title>'+escapeHtml(row.date)+' · 区间累计 '+number(row.cumulativeMain,0,true)+' '+marketConfig().money+'</title></circle>':'').join('')+'<text x="'+left+'" y="'+(height-9)+'">'+rows[0].date+'</text><text x="'+(width-right)+'" y="'+(height-9)+'" text-anchor="end">'+rows.at(-1).date+'</text></svg></div>';
}
/** 展示逐日主力净额和区间相抵结果，明确告知不能据此计算实际剩余持仓。 */
function renderMainWindow(report) {
const missing=report.missingDays,rows=report.rows;
$('main-window-content').innerHTML='<h3 class="validation-heading">'+escapeHtml(report.symbol)+' / '+escapeHtml(report.name)+' · '+escapeHtml(report.start)+' 至 '+escapeHtml(report.date)+'</h3><p>含截至日，共 '+report.availableDays+' 个交易日；主力资金有效 '+report.validDays+' 日。</p><div class="window-summary"><div><span>净流入日合计（'+marketConfig().money+'）</span><strong class="positive">'+number(report.inflowDaySum,0,true)+'</strong><small>'+report.inflowDays+' 个净流入日'+(missing?' · 仅已知数据':'')+'</small></div><div><span>净流出日合计（'+marketConfig().money+'）</span><strong class="negative">'+number(report.outflowDaySum,0,true)+'</strong><small>'+report.outflowDays+' 个净流出日'+(missing?' · 仅已知数据':'')+'</small></div><div class="window-net"><span>区间累计净流入（'+marketConfig().money+'）</span><strong class="'+tone(report.net)+'">'+number(report.net,0,true)+'</strong><small>'+(missing?'缺失日导致完整区间净额不可计算':report.net>0?'此区间累计净流入':report.net<0?'此区间累计净流出':'此区间净额为零')+'</small></div></div><div class="validation-note"><strong>主力实际剩余资金：无法计算。</strong> 资金流记录的是成交方向净额，没有期初持仓和真实主力账户身份。累计净额从本区间起点记账，不能表示当前还持有多少资金；累计为负也不会归零。</div>'+(report.availableDays<report.requestedDays?'<p class="validation-error">最近一年可查询范围内，截至此日仅有 '+report.availableDays+' 个交易日，不足请求的 '+report.requestedDays+' 日。合计仅覆盖上方显示的实际区间。</p>':'')+(missing?'<p class="validation-error">'+missing+' 个交易日主力资金缺失；已知日净额合计 '+number(report.knownNet,0,true)+' '+marketConfig().money+'，仅供部分数据参考。累计曲线从首个缺失日起中断，缺失值不按零处理。</p>':'')+mainWindowChart(rows)+'<p>区间净额 = 净流入日合计 + 净流出日合计（负数）。日级接口只提供净额，上述两项不是买入、卖出总金额。<a class="accent" href="https://openapi.futunn.com/futu-api-doc/quote/get-capital-flow.html" target="_blank" rel="noopener">查看富途字段口径 ↗</a></p><div class="path-table"><table><thead><tr><th>序号</th><th>'+marketConfig().zone+'日期</th><th>大单净额</th><th>特大单净额</th><th>主力净额</th><th>区间累计净额</th><th>收盘价</th><th>单日涨跌</th></tr></thead><tbody>'+rows.map((row,i)=>'<tr><td>'+(i+1)+'</td><td>'+escapeHtml(row.date)+'</td><td class="'+tone(row.big)+'">'+number(row.big,0,true)+'</td><td class="'+tone(row.super)+'">'+number(row.super,0,true)+'</td><td class="'+tone(row.main)+'">'+number(row.main,0,true)+'</td><td class="'+tone(row.cumulativeMain)+'">'+number(row.cumulativeMain,0,true)+'</td><td>'+number(row.close,2)+'</td><td class="'+tone(row.change)+'">'+number(row.change,2,true)+(Number.isFinite(row.change)?'%':'')+'</td></tr>').join('')+'</tbody></table></div><p>资金单位：'+marketConfig().money+'；收盘价：'+marketConfig().currency+'／前复权。累计为每日主力净额之和，不计算持仓市值随价格变化。每日先用原始精度求和，显示值四舍五入，可能出现尾数差。</p>';
}
/** 从股票详情直接查询该股票的主力区间资金。 */
function handleMainWindowClick(event) {const target=event.target.closest('[data-main-window]');if(target)openMainWindow(target.dataset.mainWindow);}
/** 从总览打开默认股票的主力区间观察。 */
function openDefaultMainWindow() {openMainWindow();}
$('main-window-open').addEventListener('click',openDefaultMainWindow);$('main-window-form').addEventListener('submit',queryMainWindow);document.addEventListener('click',handleMainWindowClick);
